anno = mesediriferimento[0:4]

try:
    maxProgressivoDf = spark.sql(f"select max(id) as id from fat_delta.allpreseincarico_conLotti where left(presaincarico_data,4) = '{anno}'")
    if maxProgressivoDf.count() >0:
         maxProgressivo = maxProgressivoDf.collect()[0]['id'] 
    else:
         maxProgressivo = 0
except:
    maxProgressivo = 0
